} from '@google/gemini-cli-core';
import { loadSettings } from './settings.js';
import {
  isWorkspaceTrusted,
  resetTrustedFoldersForTesting,
} from './trustedFolders.js';
import { createExtension } from '../test-utils/createExtension.js';
import { EXTENSIONS_DIRECTORY_NAME } from './extensions/variables.js';
import { ExtensionManager } from './extension-manager.js';

const mockHomedir = vi.hoisted(() => vi.fn(() => '/tmp/mock-home'));
vi.mock('os', async (importOriginal) => {
  const mockedOs = await importOriginal<typeof os>();
  return { ...mockedOs, homedir: mockHomedir };
});
vi.mock('./trustedFolders.js', async (importOriginal) => {
  const actual = await importOriginal<typeof import('./trustedFolders.js')>();
  return { ...actual, isWorkspaceTrusted: vi.fn() };
});
vi.mock('@google/gemini-cli-core', async (importOriginal) => {
  const actual =
    await importOriginal<typeof import('@google/gemini-cli-core')>();
  return {
    ...actual,
    homedir: mockHomedir,
    KeychainTokenStorage: vi.fn().mockImplementation(() => ({
      getSecret: vi.fn(),
      setSecret: vi.fn(),
      deleteSecret: vi.fn(),
      listSecrets: vi.fn(),
      isAvailable: vi.fn().mockResolvedValue(true),
    })),
    loadAgentsFromDirectory: vi
      .fn()
      .mockImplementation(async () => ({ agents: [], errors: [] })),
    loadSkillsFromDir: vi.fn().mockImplementation(async () => []),
  };
});

describe('concurrency verify', () => {
  let tempHomeDir: string;
  let tempWorkspaceDir: string;
  let userExtensionsDir: string;
  let extensionManager: ExtensionManager;

  beforeEach(() => {
    vi.clearAllMocks();
    (
      KeychainTokenStorage as unknown as ReturnType<typeof vi.fn>
    ).mockImplementation(() => ({
      getSecret: vi.fn(),
      setSecret: vi.fn(),
      deleteSecret: vi.fn(),
      listSecrets: vi.fn(),
      isAvailable: vi.fn().mockResolvedValue(true),
    }));
    vi.mocked(loadAgentsFromDirectory).mockResolvedValue({
      agents: [],
      errors: [],
    });
    vi.mocked(loadSkillsFromDir).mockResolvedValue([]);
    tempHomeDir = getRealPath(
      fs.mkdtempSync(path.join(os.tmpdir(), 'gemini-cli-verify-home-')),
    );
    tempWorkspaceDir = getRealPath(
      fs.mkdtempSync(path.join(tempHomeDir, 'gemini-cli-verify-ws-')),
    );
    userExtensionsDir = path.join(tempHomeDir, EXTENSIONS_DIRECTORY_NAME);
    fs.mkdirSync(userExtensionsDir, { recursive: true });
    vi.mocked(os.homedir).mockReturnValue(tempHomeDir);
    vi.mocked(isWorkspaceTrusted).mockReturnValue({
      isTrusted: true,
      source: undefined,
    });
    vi.spyOn(process, 'cwd').mockReturnValue(tempWorkspaceDir);
    const settings = loadSettings(tempWorkspaceDir).merged;
    extensionManager = new ExtensionManager({
      workspaceDir: tempWorkspaceDir,
      requestConsent: vi.fn().mockResolvedValue(true),
      requestSetting: vi.fn().mockResolvedValue(''),
      settings,
    });
    resetTrustedFoldersForTesting();
  });

  afterEach(() => {
    fs.rmSync(tempHomeDir, { recursive: true, force: true });
    vi.restoreAllMocks();
  });

  it('shares the same in-flight promise and array reference', async () => {
    createExtension({ extensionsDir: userExtensionsDir, name: 'a', version: '1.0.0' });
    createExtension({ extensionsDir: userExtensionsDir, name: 'b', version: '1.0.0' });
    const p1 = extensionManager.loadExtensions();
    const p2 = extensionManager.loadExtensions();
    expect(p1).toBe(p2);
    const [a1, a2] = await Promise.all([p1, p2]);
    expect(a1).toBe(a2);
    expect(a1).toBe(extensionManager.getExtensions());
    expect(a1.map((e) => e.name).sort()).toEqual(['a', 'b']);
  });

  it('throws after load resolves', async () => {
    await extensionManager.loadExtensions();
    expect(() => extensionManager.loadExtensions()).toThrow(
      'Extensions already loaded, only load extensions once.',
    );
  });

  it('returns empty array when dir missing', async () => {
    fs.rmSync(userExtensionsDir, { recursive: true, force: true });
    const exts = await extensionManager.loadExtensions();
    expect(exts).toEqual([]);
  });

  it('throws on duplicate names across directories', async () => {
